<?php require __DIR__.'/bootstrap.php'; $key='';try{$key=setting('google_maps_browser_key');}catch(Throwable $e){}?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Réservation · ISLEM VTC</title><link rel="stylesheet" href="/assets/style.css"></head><body><header class="site-header"><div class="shell nav"><a class="brand" href="/">ISLEM VTC<small>CHAUFFEUR PRIVÉ · PARIS</small></a><a href="/">← Retour à l'accueil</a></div></header><main class="interior shell"><div class="section-heading"><span class="eyebrow">ÉTAPE 3 & 4</span><h2>Confirmer votre réservation</h2></div><div class="page-grid"><div class="panel"><h2>Votre chauffeur</h2><div id="drivers"><p class="muted">Chargement des chauffeurs…</p></div><hr><h2>Informations personnelles</h2><form id="booking"><div class="field"><label>Prénom</label><input name="first_name" required maxlength="120"></div><div class="field"><label>Nom</label><input name="last_name" required maxlength="120"></div><div class="field"><label>Téléphone</label><input name="phone" type="tel" required></div><div class="field"><label>E-mail</label><input name="email" type="email" required></div><div class="field"><label>Adresse du client (Google Places)</label><input id="address" name="address" required placeholder="Commencez à écrire votre adresse"></div><div class="field"><label>Date et heure de prise en charge</label><input name="when" type="datetime-local" required></div><div id="message"></div><button type="submit" class="primary-wide">Envoyer ma demande de réservation</button></form></div><aside class="panel"><h2>Récapitulatif</h2><div id="summary"></div><p class="mini muted">Le montant sera recalculé au moment de l'enregistrement selon la circulation.</p><div class="tags"><span class="tag">✓ Prix transparent</span><span class="tag">✓ Paiement à configurer</span></div></aside></div></main><footer class="footer">ISLEM VTC · Demande soumise à confirmation</footer><script>window.ISLEM_CSRF=<?= json_encode(csrf()) ?>;</script><script src="/assets/app.js"></script><script>
const t=JSON.parse(sessionStorage.getItem('islem_trip')||'null');if(!t){$('#summary').textContent='Estimez votre trajet depuis la page d’accueil.';}else{$('#summary').innerHTML='<p><strong>Départ :</strong> '+safe(t.pickup)+'</p><p><strong>Arrivée :</strong> '+safe(t.dropoff)+'</p><h2>'+Number(t.price.total).toLocaleString('fr-FR',{style:'currency',currency:'EUR'})+'</h2>';}function safe(x){return String(x).replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;')}
fetch('/api/drivers.php').then(r=>r.json()).then(j=>{$('#drivers').innerHTML=j.drivers.length?j.drivers.map(d=>'<div class="card"><strong>'+safe(d.first_name)+' '+safe(d.last_name)+'</strong><p class="mini">'+safe(d.make||'')+' '+safe(d.model||'')+'</p><div class="tags"><span class="tag">'+(d.verified?'✓ Chauffeur vérifié':'Vérification en cours')+'</span><span class="tag">'+(d.compliant?'✓ Véhicule conforme':'Vérification véhicule en cours')+'</span></div></div>').join(''):'<p class="muted">Aucun chauffeur actuellement affiché. Votre demande reste soumise à confirmation.</p>';}).catch(()=>{$('#drivers').textContent='Chauffeurs indisponibles temporairement.'});
$('#booking').addEventListener('submit',async event=>{event.preventDefault();if(!t){$('#message').textContent='Aucun trajet sélectionné';return;}let f=new FormData(event.target);let data={...t};delete data.price;for(let [k,v] of f.entries())data[k]=v;try{let r=await fetch('/api/book.php',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-Token':window.ISLEM_CSRF},body:JSON.stringify(data)});let j=await r.json();if(!r.ok||!j.ok)throw Error(j.error||'Erreur');location.href='/confirmation.php?code='+encodeURIComponent(j.code)+'&link='+encodeURIComponent(j.track);}catch(e){$('#message').className='error';$('#message').textContent=e.message}});
</script><?php if($key): ?><script defer src="https://maps.googleapis.com/maps/api/js?key=<?= urlencode($key) ?>&libraries=places&callback=googleReady"></script><?php endif; ?></body></html>